function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Draw yin yang symbol
  ctx.beginPath();
  ctx.arc(W/2, H/2, Math.min(W, H)/4, 0, 2 * Math.PI);
  ctx.stroke();

  // Draw yin and yang dots
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + Math.min(W, H)/8 * Math.cos(t), H/2 + Math.min(W, H)/8 * Math.sin(t), Math.min(W, H)/16, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + Math.min(W, H)/8 * Math.cos(t + Math.PI), H/2 + Math.min(W, H)/8 * Math.sin(t + Math.PI), Math.min(W, H)/16, 0, 2 * Math.PI);
  ctx.fill();

  // Draw stick figures in balance
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2 - Math.min(W, H)/8 * Math.cos(t), H/2 - Math.min(W, H)/8 * Math.sin(t));
  ctx.lineTo(W/2 - Math.min(W, H)/8 * Math.cos(t), H/2 - Math.min(W, H)/4);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - Math.min(W, H)/8 * Math.cos(t), H/2 - Math.min(W, H)/4, Math.min(W, H)/16, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.min(W, H)/8 * Math.cos(t), H/2 + Math.min(W, H)/8 * Math.sin(t));
  ctx.lineTo(W/2 + Math.min(W, H)/8 * Math.cos(t), H/2 + Math.min(W, H)/4);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + Math.min(W, H)/8 * Math.cos(t), H/2 + Math.min(W, H)/4, Math.min(W, H)/16, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
